#include "stdlib/math/base/special/powm1f.h"
#include "stdlib/math/base/special/absf.h"
#include "stdlib/math/base/special/expm1.h"
#include "stdlib/math/base/special/lnf.h"
#include "stdlib/math/base/special/powf.h"
#include "stdlib/math/base/special/truncf.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/assert/is_infinitef.h"
#include "stdlib/math/base/special/fmodf.h"

/**
* Evaluates `bˣ - 1`.
*
* @param b    base
* @param x    exponent
* @return     function value
*
* @example
* float out = stdlib_base_powm1f( 2.0f, 3.0f );
* // returns 7.0
*
* @example
* float out = stdlib_base_powm1f( 4.0f, 0.5f );
* // returns 1.0
*/
float stdlib_base_powm1f( const float b, const float x ) {
	float result;
	float bc;
	float y;

	if ( stdlib_base_is_nanf( b ) || stdlib_base_is_nanf( x ) ) {
		return 0.0f / 0.0f; // NaN
	}
	if ( x == 0.0f ) {
		// Any number raised to zero (including 0) is always 1 => b^0 - 1 = 0
		return 0.0f;
	}
	if ( b == 0.0f ) {
		// Zero raised to any number (except 0) is always zero => 0^x - 1 = -1
		return -1.0f;
	}
	bc = b;
	if ( b < 0.0f && stdlib_base_fmodf( x, 2.0f ) == 0.0f ) {
		// If `x` is even, recognize that `(-b)**x == (b)**x`...
		bc = -b;
	}
	if ( bc > 0.0f ) {
		if ( stdlib_base_absf( x * ( bc - 1.0f ) ) < 0.5f || stdlib_base_absf( x ) < 0.2f ) {
			// No good/quick approximation for ln(b)*x, so we have to evaluate...
			y = stdlib_base_lnf( bc ) * x;
			if ( y < 0.5f ) {
				return (float)stdlib_base_expm1( (double)y );
			}
		}
	} else if ( stdlib_base_truncf( x ) != x ) {
		// Exponentiation would yield a complex result...
		return 0.0f / 0.0f; // NaN
	}
	result = stdlib_base_powf( bc, x ) - 1.0f;
	if ( stdlib_base_is_infinitef( result ) || stdlib_base_is_nanf( result ) ) {
		return 0.0f / 0.0f; // NaN
	}
	return result;
}
